?><!doctype html><html><head><meta charset="utf-8"><title>Trial Locations</title><link rel="stylesheet" href="style.css"></head><body><main><header><h1>PHILSURIN</h1><span><?=e($_SESSION['user']['username'])?> | <a href="index.php">ENCODING</a> <a href="?logout=1">LOG OUT</a></span></header><section class="card"><h2>Trial Locations</h2><p class="hint">Each Location ID with encoded data is listed once. Open a report to view all grading records for that location.</p><table class="locations"><thead><tr><th>LOCATION ID</th><th>LOCATION OF PROJECT</th><th>SIZE OF LOCATION</th><th>ENCODED ROWS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['location_id'])?></td><td><?=e($r['project_location'])?></td><td><?=e($r['location_size'])?></td><td><?=e($r['encoded_rows'])?></td><td><a class="smallbtn" href="report.php?location=<?=urlencode($r['location_id'])?>">REPORT</a><?php if(($_SESSION['user']['role']??'')==='admin'):?><form method="post" class="inline" onsubmit="return confirm('Delete all records for this Location ID?')"><input type="hidden" name="location_id" value="<?=e($r['location_id'])?>"><button class="danger" name="delete">DELETE</button></form><?php endif?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No encoded trial locations yet.</td></tr><?php endif?></tbody></table><div class="location-actions"><a class="smallbtn" href="index.php">STORE DATA</a><a class="smallbtn" href="export.php">EXPORT EXCEL</a><a class="smallbtn" href="index.php">ASSIGN NO-LOCATION ROWS</a></div></section></main><style>.locations{width:100%;border-collapse:collapse}.locations th,.locations td{border:1px solid #d7e0ea;padding:11px;text-align:left}.locations th{background:#dff2ea;color:#087f59;font-size:10px}.locations td{font-size:12px}.smallbtn,.danger{display:inline-block;border:0;border-radius:6px;padding:6px 9px;background:#087f59;color:#fff;text-decoration:none;font-size:10px;font-weight:bold;margin-right:5px}.danger{background:#c62828;cursor:pointer}.inline{display:inline}</style></body></html>
